import { AdminApp, type AdminBranding } from "@emdash-cms/admin";
import type { Messages } from "@lingui/core";
// @ts-ignore - virtual module generated by integration
import { pluginAdmins } from "virtual:emdash/admin-registry";
// @ts-ignore - virtual module generated by integration
import { authProviders } from "virtual:emdash/auth-providers";

interface AdminWrapperProps {
	locale: string;
	messages: Messages;
	adminBranding?: AdminBranding;
}

export default function AdminWrapper({ locale, messages, adminBranding }: AdminWrapperProps) {
	return (
		<AdminApp
			pluginAdmins={pluginAdmins}
			authProviders={authProviders}
			adminBranding={adminBranding}
			locale={locale}
			messages={messages}
		/>
	);
}
